INSERT INTO Definition (word_id, language_id, pos_id, definition, example)
VALUES
(6189,3,1,'တစ်ဆယ့်ခုနစ်လုံးမြောက်မွန်ဗျည်း။',NULL)
,(6190,3,4,'တွန်းကန်သည်။ (လှေကမ်းရောက်ချိန်တွင် တွန်းကန်သကဲ့သို့ တွန်းကန်သည်။)',NULL)
,(6191,3,1,'ဘေးဖက်။','ထကဲသ္ၚိ = အိမ်ဘေး။')
,(6192,3,1,'ကြွက်လျှောက်။',NULL)
,(6193,3,4,'ကွဲသည်။','‘ပ္ၚာန်တိုက်ဂှ် ထကးအာရ။’ = ‘ကြွေပန်းကန်သည် ကွဲသွားပြီ။’ || ဖျုန်ဂြိုဟ်ထကး = နှလုံးကွဲသည်။')
,(6194,3,4,'ကွဲပြီးပြန့်ကျဲသည်။',NULL)
,(6195,3,1,'ချက်­ဆုံသော ကြွက်သားနှင့်အကြောစု။ တကျည်း။','ထကေၚ်ဗၠေတ် = တကျည်း လွဲသည်။')
,(6196,3,4,'‘ဒကတ်’ ရှု။',NULL)
,(6197,3,1,'ဝမ်းကိုက်ရောဂါ။',NULL)
,(6198,3,4,'ဖြတ်သည်။ ပြတ်သည်။','“ကုတ်ထောံတၞံဆုဂှ် ထကုတ်အာရ။” = ထိုသစ်ပင်ကိုဖြတ်လိုက်ရာ ပြတ်သွားသည်။”')
,(6198,3,1,'ဖြတ်ထားသောအပိုင်း။ အပိုင်း။','ဆုထကုတ် = သစ်အပိုင်း။')
,(6199,3,1,'ဖွတ်။','ခၟာဲထကောတ် = ဖွတ်ဥ။')
,(6200,3,4,'လှန့်သည်။ ခြောက်လှန့်သည်။','“လ္ပထကိုတ်အဲ အဲလကိုတ်စလောဲဒၟံၚ်ရောၚ်။” = “ငါ့ကို မလှန့်ပါနှင့်၊ ငါလန့်တတ်သည်။”')
,(6201,3,1,'၁။ အဖုံး။','ထကိုပ်ပလင် = ပုလင်းအဖုံး။ || သ္ၚာထကိုပ် = ဒုကုဋ်သင်္ကန်း။')
,(6201,3,1,'၂။ ခေါင်းဆောင်။ အကြီးအကဲ။','ထကိုပ်ပၞာန် = စစ်ခေါင်းဆောင်။ စစ်ဦးစီး။')
,(6202,3,1,'ပုတ်သင်ညို။',NULL)
,(6202,3,4,'အိပ်ငိုက်သည်။',NULL)
,(6203,3,4,'အကြောဆွဲသည်။',NULL)
,(6204,3,1,'ဖျာ။','“လးကဵုထကဝ် လးယာတ်တုဲ ကဵုသ္တိက်ရ။” (ဇ—၃ဝ၂။ အစွောံ။) = “ဖျာကို၄င်း အဝတ်ကို၄င်း ခင်းပေးပြီးလျှင် အိပ်စေ၏။”')
,(6205,3,4,'မွှေသည်။','ထကဵုကွာၚ် = မုန့်မွှေသည်။ || ကွာၚ်ထကဵု = ဟာလဝါမုန့်။')
,(6206,3,1,'ကံ့ကူဆံ။ ကျောက်တံ။',NULL)
,(6206,3,4,'၁။ ချွန်ထက်အောင်လုပ်သည်။ သွေးသည်။','ချူထကောဟ် = ထက်အောင်သွေးသည်။')
,(6206,3,4,'၂။ ချောအောင်သပ်သည်။','“ဗာ်ဒုန်ဂှ်တုဲ ထကောဟ် ထောံညိ။” = “ဝါးကိုခုတ်ပြီး ချောအောင်သပ်လိုက်ပါ။”')
,(6207,3,1,'ပစ္စည်းထည့်သောကျည်တောက်။','ထကိုအ်တၞိၚ် = အပ်ထည့်သော ကျည်တောက်။ || ထကိုအ်လဴ = မျှားထည့်သောကျည်တောက်။')
,(6208,3,4,'ခြေထောက်ကိုကားသည်။',NULL)
,(6209,3,1,'ကကြိုးတန်ဆာ။','ထၚးစိၚ် = ဆင်ကကြိုးတန်ဆာ။ || ‘လ္ၚး’ ရှု။')
,(6210,3,4,'စောင်းသည်။','ထစေၚ်ဒလိန် = စွေစောင်းသည်။ || တိက်လက်ဒစေၚ် = ဘေးစောင်းအနေအထားဖြင့် အိပ်သည်။')
,(6211,3,4,'ခိုက်ရန်ဖြစ်သည်။ ငြင်းခုံသည်။','“ကလောကဵုကလောတံဂှ် ဟွံဂပ်ဂဝ် ထညက်ထညောန်ရၚ်သ္ကံရ။ ဂပ်ဂဝ်သၟဟ်သၟန်တဴလၟိုန်ရ။” = “ဆွေမျိုးအချင်းချင်း ခိုက်ရန်မဖြစ် သင့်ပါ၊ အမြဲတစေ ညီညွတ်သင့်သည်။”')
,(6211,3,1,'ခိုက်ရန်။ ခိုက်ရန်ဖြစ်ခြင်း။ ငြင်းခုံခြင်း။ အငြင်းအခုံ။','“ပဟိုတ်ကဵုထညက်ထညောန်သွေက်ဇဵုအမာတ်ၜါဂှ်တုဲ ဥရဂဇာတ်ဂှ် ကျာ်တြဲတွံရ။” (ဇ— ၁၅၄။ အစွောံ။) = “အမတ်ကြီးနှစ်ဦးတို့၏ ငြင်းခုံခိုက်ရန်ဖြစ်ခြင်းကို အကြောင်းပြု၍ ဥရဂဇာတ်ကို မြတ်စွာဘုရားဟောတော်မူ၏။” || ‘ခညက်ခညောန်’ ဟုလည်းရေးသည်။')
,(6212,3,4,'မျက်နှာရှုံ့သည်။ ရှုံ့မဲ့သည်။','“ကၞုဲဂှ် — ဍေံထညက်ဓလန်မုက်မတ် ဍေံတုဲ ဍေံထ္ၜးကဵုရသိတံရ။” (ဇ—၂၉၉။ အစွောံ။) = “ထိုမျောက်သည် မျက်နှာရှုံ့မဲ့ခြင်းကို ရ သေ့တို့အား လုပ်ပြလေ့၏။”')
,(6213,3,4,'တွန့်သည်။','“မၞိဟ်ဗျု ဖျုန်ထညောတ်ဒၟံၚ်ရ။” = “လူအိုအသားအရေတွန့်နေသည်။”')
,(6214,3,4,'မျက်နှာရှုံ့မဲ့သည်။ မျက်မှောင်ကြုတ်သည်။','“ညးစပၞဴဖျးလောန်တုဲ မုက် ညးထညောန်တဴရ။” = “သူသံပုရာသီးစားရာ ချဉ်လွန်းသောကြောင့် သူ့မျက်နှာရှုံ့မဲ့နေသည်။” || “(ဂစေံကၠၚ်ဟိုက်ဝွံဂှ်) မုက်ဍေံဂှ် မၞးတံရံၚ်ရ။ ၜိုန်ဍေံဟွံထေဲပၞတ်ကဵုညးဏီဂှ် မုက်ဍေံထညန်ဒၟံၚ် တုဲရ။ ယာံဍေံထေဲပၞတ်ကဵုညးတုဲဂှ် မုက်ဍေံထညန်ဇၞော်တိုန်တုဲ သိက်မၞးတံသ္ပရော။ ညးဂှ် မဂံၚ် ဆိုက်ဍေံရော” ခဍာ်ဂး။ (ဇ—၂၇ဝ။ အစွောံ။) = “ဤခင်ပုပ်ငှက်၏မျက်နှာကို သင်တို့ကြည့်ကြ ကုန်လော့။ အမျက်မထွက်သေးဘဲလျက်လည်း မျက်နှာသည် (မရှုချင်စဖွယ်) ရှုံ့မဲ့နေ၏။ အမျက် ထွက်သောအခါ­ မျက်နှာသည် ပို၍ရှုံ့မဲ့လာသည်ရှိသော်ကား သင်တို့သည် အဘယ်သို့ပြုမည်နည်း။ အဘယ်သူသည် သူ့အနားသို့ ချဉ်းကပ်ဝံ့ပါမည်နည်း” ဟုကျီးဆို၏။')
,(6215,3,4,'တိုက်မိသည်။ ထိမိသည်။','ထဍဳရၚ်သ္ကအ် = တစ်ယောက်နှင့်တစ်ယောက် တိုက်မိသည်။')
,(6216,3,4,'ထိသည်။ ခတ်သည်။ တိုက်သည်။ ထိခိုက်သည်။ ထိခတ်သည်။','“ကာလလိုန်ၜါဟွံကောံရၚ်သ္ကအ်ဂှ် ထဍဳလယတ်ဟွံမွဲရ။ လိုန်ၜါဂှ် ကောံဒှ်မွဲစွံတုဲ ထဍဳလယတ်တဴ ကေုာံရၚ်သ္ကအ်ရောၚ်သွံ။” (ဇ—၄ဝ၈။ အစွောံ။) = “လက်ကောက်နှစ်ကွင်းတို့ အချင်းချင်းမစုမိ ကြသေးစဉ် ထိခိုက်တိုက်ခတ်မှုမရှိ။ လက်ကောက်နှစ်ကွင်းတို့ စုစည်းမိကြသောအခါ­ အချင်း ချင်းထိခတ်ကြကုန်၏။”')
,(6217,3,3,'အလယ်ဖြစ်သော။','ကောန်ထဍဲ = အကြီးဆုံးနှင့် အငယ်ဆုံးမဟုတ်သော အလယ်အလတ်သားသမီး။')
,(6217,3,3,'အလယ်ဖြစ်သော။','တဲထဍဲ = လက်သူကြွယ်။')
,(6218,3,1,'ညလယ်ခေါင်အချိန်။ သန်းခေါင်ယံအချိန်။',NULL)
,(6219,3,1,'အလယ်။','“ယြဴပူဂဵုမွဲပတၠဂုန် စိုပ်ဒေါဝ်ထဍဲဟာန်တၠပညာဂမၠိုၚ် ဇကုဂှ် ညးဟွံသၟာန် လ္ပဟီုပ္တိတ်စညိ။” (သၠပတ်ဒ္ၚောဝ်သၜောံ) = “ဂုဏ်ကျေးဇူးနှင့်ပြည့်စုံသော အကြင်ပုဂ္ဂိုလ်သည် ပညာရှိများအလယ်သို့ ရောက်သောအခါ­ မိမိအား သူတစ်ပါးတို့မမေးပါက ပြောဆိုထုတ်ဖော်ခြင်းမပြုရာ။”')
,(6220,3,3,'‘ခ္ဍဴ’ ရှု။',NULL)
,(6221,3,1,'မီးခွက်။ မီးအိမ်။',NULL)
,(6222,3,4,'၁။ ခေါက်သည်။','ထဍံက်က္ဍိုပ် = ခေါင်းခေါက်သည်။')
,(6222,3,4,'၂။ သင်အံသည်။','ထဍံက်လိက် = စာအံသည်။')
,(6223,3,4,'ရှက်စေသည်။ ရှက်အောင်ပြုသည်။','‘ဟီုထဍိုက်’ ရှု။')
,(6224,3,4,'အရှက်ခွဲသည်။ အရှက်ကွဲစေသည်။','‘ဂဍိုက်ဂဝ’ ရှု။')
,(6225,3,4,'ခလုတ်တိုက်သည်။','“ကောန်ၚာ်ဒြေပ်ဂှ် ထဍိၚ်ဒးဒုန်ဒကုတ်ဂှ်တုဲ လောတ်စှ်ေရ။” = “ပြေးသောကလေးသည် ဝါးပိုင်းကိုု ခလုတ်တိုက်မိပြီး လဲကျသွားသည်။”')
,(6226,3,4,'ပြေးလိုက်သည်။','ထဍေၚ်ဗက် = နောက်ကပြေးလိုက်သည်။ || ထဍေၚ်ကမၠတ် = သူခိုးလိုက်သည်။ || “(ဗောဓိသတ်) ထဍေၚ်ဗက်ကၠဵုဂှ် ကၠဵုဒဴတိတ်အာဂြိုပ်ဇၞော်ရ။” (ဇ—၂၄၁။ အစွောံ။) = “ဘုရားလောင်းသည် ထိုမြေခွေးကို ပြေးလိုက်သည်ရှိသော် မြေခွေးသည် တောကြီးသို့ ပြေးဝင်သွား၏။”')
,(6227,3,4,'ထူထဲသည်။ ပြည့်နှက်သည်။','ထဍတ်ပေၚ် = ပြည့်နှက်သည်၊ အခေါင်းပိတ်ဖြစ်သည်။ || ‘ဍတ်’ ရှု။')
,(6228,3,1,'လက်ဖြောက်တီးခြင်း။','‘ခဍတ်တဲ’ ရှု။')
,(6229,3,1,'စည်း။ (တူရိယာပစ္စည်း)',NULL)
,(6230,3,4,'၁။ ကလော်သည်။','“ထဍဟ်ပ္တိတ်အိက်ကတောဝ်။” = “နားချေးကို ကလော် ထုတ်သည်။”')
,(6230,3,4,'၂။ (ကြိုးကို) ခတ်သည်။','ထဍဟ်ဇုက်တ္ၚ = လေးကြိုးကိုခတ်သည်။')
,(6230,3,4,'၃။ (လက်ဖြင့်) တီးခေါက်သည်။','“ဆုဗ္ဒဝ်ဂှ် နသနေံတဲ ဍေံတံထဍဟ်တုဲ—။” (ဇ—၂၄၅။ အစွောံ။) = “ဆီးပင်သို့ လက်သီးဖြင့်ခေါက်ကုန်၍—။” (ညောင်ကန်)')
,(6230,3,4,'၄။ ရုန်းကန်ရိုက်ခတ်သည်။ ပြန်ကန်သည်။','“(မၚ်ဗၠာဲလၞုဟ်ဂှ်) သီုမမှုဲဒၟံၚ်သတိက် ဒွါန်တိုန်ဆုဗလဲ ရပ်ကၞာၚ်မွဲ ဗလဲ ဖျေံမဒ္ဂူကဵုဇကု တဲဝးပကဝ်အာတုဲ မုဟ်ကၞာၚ်ဗလဲမသိဟ်ဂှ် ထဍဟ်တိုန်ပၠန် ဒွအ်ဒးမတ် မတ်လီုအာ။” (ဇ—၇၁။ အစွောံ။) = “ပျင်းရိသောလုလင်သည် အိပ်မှုန်စုံမွှားဖြင့် ရေခတက်ပင်သို့ တက်၍ တစ်ခုသောအကိုင်းကိုကိုၚ်လျက် မိမိဖက်သို့ဆွဲချကာ လက်ဖြင့်ချိုးသည်ရှိသော် ကျိုးသောအကိုင်းစွန်းသည် ပြန်ကန်၍ မျက်စိကိုရိုက်ခတ်မိသဖြင့် မျက်စိပျက်သွား၏။”')
,(6230,3,4,'၅။ ထိုးသည်။ ဆွသည်။','“ညံၚ်ဇြုံဇာတ် ညးမထဍဟ်စုတ်ကဵုလေံတုဲ ရဴယိုက်ပ္တိုန်ဒနံက်ဂှ်ကီုရ။” (ဇ— ၂၅၁။ အစွောံ။) = “တုတ်နှင့်ထိုးဆွသည်ရှိသော် မြွေဟောက်သည် ပါးပျဉ်းကို ထောင်သကဲ့သို့။”')
,(6231,3,4,'ထိုးဆွသည်။','“အိက်ဇမ္ကဟ်ထဍဟ်က္တဵု။” = “ချေးခြောက်ကို ထိုးဆွသည်။” ( = ချေးခြောက်ကို ရေနှူးသည်။)')
,(6232,3,1,'ညွန်ပျောင်း။','“အလုံရးဗြဲဟွံဂူ — မပ္တံသြာၚ်ကၟာလ္စ ဍာ်သကှ် ဇတ်အာ။ ကဂမၠိုၚ် လုပ်ဒၟံၚ်ပ္ဍဲဒေါဝ်ထဍဟ်လှိုက်ရ။” (ဇ—၇၅။ အစွောံ။) = “တိုင်းအလုံး­ မိုးသည်မရွာ။ ထုံးအိုင်အစရှိသည်တို့­ ရေသည်ခန်းခြောက်၏။ ငါးတို့သည် ညွန်ပျောင်းသို့ဝင်၍ နေကြကုန်၏။”')
,(6233,3,4,'(ရေ) စစ်သည်။','“ဍာ်ထဍိုဟ်လဝ်ဂှ် သုၚ်ညိ။” = “စစ်ထားသောရေကို သောက်ပါ။”')
,(6233,3,1,'ထဍိုဟ်ဍာ် = ရေစစ်။','‘သ္ဍိုဟ်’ ဟုလည်းတွေ့ရသည်။')
,(6234,3,4,'တွန့်တိုသည်။','“မၞုံအဇ္ၛာသယ မဟွံဂွံထဍိုဟ်တုဲ—။” (ဇ—၅၅။ အစွောံ။) = “မတွန့်တိုသောအလိုရှိသည်ဖြစ်၍—။” (ညောင်ကန်) (အဇ္ၛာသယ = အလို။ စိတ်အလို။ နှလုံး အလို။)')
,(6235,3,1,'သေတ္တာ။ အစ်။','ထဍအ်ဇဗၠု = ကွမ်းအစ်။')
,(6236,3,1,'၁။ စောင်း။ (တူရိယာ)','တိၚ်ထဏ = စောင်းတီးသည်။')
,(6236,3,1,'၂။ တိုင်ထိပ်ပေါ်တွင် အနံလိုက် ကန့်လန့်ထားသောသစ်သား။ ခေါင်လျှောက်။ (ပါဠိ—သံဃာဋ)','‘ဒၟၚ်’ လည်းရှု။')
,(6237,3,4,'၁။ ထောင်းသည်။','ထဏက်မြေက် = ငရုပ်သီးထောင်းသည်။ || “တၞးဆု ဂမ္တၚ်မသုန်သာ် သစ္ဆုဂမ္တၚ်မသုန်သာ် ထဏက်ဍိုတ်တုဲ—။” (ဇ—၁၃ဝ။ အစွောံ။) = “သစ်ရွက် ခါးငါးမျိုး သစ်သီးခါးငါးမျိုးတို့ကို ညက်အောင်ထောင်း၍—။”')
,(6237,3,4,'၂။ တံတောင်နှင့်တွက်သည်။ တံတောင်ဖြင့်ထောင်းသည်။','“ယွံတၠသ္ၚိ၊ အဲသၟိက်ဂွံထဏက်ဝေၚ် က္ဍိုပ်တၠသ္ၚိမွဲလစုတ်ညိမူဒှ်ရော” သၟတ်ဗြဴဂးကဵုဗမၞး။ (ဇ—၆၂။ အစွောံ။) = “အရှင်၊ အရှင့်ဦးခေါင်းကို တစ်ချက်မျှ အကျွန်ုပ် ထောင်းကစားလို၏။”')
,(6238,3,4,'‘ထၞိက်’ ရှု။',NULL)
,(6239,3,4,'ခေါင်းမာသည်။ ဆုံးမရခက်သည်။','ဓလဵုထဏံၚ် = လူပါးဝသည်။ ရိုင်းပျသည်။')
,(6240,3,4,'ကပ်သည်။ ငြိသည်။ ကပ်ပါသည်။ ငြိတင်သည်။','“ဂြောဝ်ဂှ် ဍေံဖျိန်ကဵုသၟိၚ်တုဲ ဖျုန်ထနေန်ဒၟံၚ်ပ္ဍဲဇုတ်ဂှ် တၞဟ်နသွက်ဇကုစဂှ် ကဵုဗောဓိသတ်ဖျိန်လဝ်ရ။” (ဇ— ၅၃၁။ အစွောံ။) = “စားတော်ချက်သည် မင်းအတွက်ချက်ပေးပြီးနောက် အရိုး­ကပ်နေသောအ သားကို မိမိစားရန်အတွက် ဘုရားလောင်းအား ချက်ထားစေ၏။” || လက်ချောင်း­ ငြိတင်ကပ်ပါ၍ ရရှိ၏။” || “သၠစွောံမွဲတၞုၚ်ဂှ် ထနေန်ကၠုၚ်ပ္ဍဲသော်အဲ နူသ္ၚိဒကာဂှ်” ဣသိဂး။ (ဇ— ၈၉။ အစွောံ။) = “ဒါဒကာ၊ သင်တို့၏အိမ်မိုးမှ တပင်သောမြက်သည် ငါ၏ဆံကျစ်ကြားတို့­ ငြိ၍ပါခဲ့၏” ဟုရသေ့ဆို၏။ (ညောင်ကန်) || “တမောံပုၚ်ဂှ် ဍေံထပက်ကျာံရ။ ကျာံဒးထပက်တုဲ ဗၞုဟ်မိၚ်ဒၠုၚ်ဂှ် ထနေန်အာဖဴကျာံဂှ်ရ။” (ဇ—၂၃၃။ အစွောံ။) = “ထမင်းချက်သည် မိကျောင်းအား မှိန်းဖြင့်ထိုး၏။ မိကျောင်းအထိုးခံရ၍ ထိုမှိန်းလှံတံသည် မိကျောင်း­ ကပ်ပါသွား၏။”')
,(6241,3,4,'တပ်မက်သည်။ မက်မောသည်။ တပ်စွန်းစွဲလမ်းသည်။ (ပါဠိ—ဂိဒ္ဓ)','“(အဝဲဂၞကျာ်အိုတ်သီု မဂေါဝ်မြဟ်တဴဂှ်) ထဏေန်ဂၠက်ဗိုန်ဒၟံၚ်ပ္ဍဲစိုတ် (ဣသိ) တုဲ လုကဴထပှ်တ္ၚဲဂှ် (ဣသိ) သတိက်ကၞပ်ချပ်ဂြၚ်ဒၟံၚ် ပ္ဍဲရုပ်ဂၞကျာ်ဂှ်ရ။” (ဇ—၂၅၁။ အစွောံ။) = “တင့်တယ်စမ္ပယ်ကုန်သော မိဖုရား၏အလုံးစုံသော ကိုယ်အင်္ဂါတို့သည် ရသေ့၏စိတ်အာရုံ­ တပ်စွန်းစွဲလမ်းနေရာ ရသေ့သည် ခုနစ်ရက်ပတ်လုံး မိဖုရားရုပ်အဆင်းကိုသာ အိပ်လျက်တွေး တောမြင်ယောင်လျက်နေ၏။”')
,(6242,3,4,'တပ်မက်သည်။ တပ်စွန်းသည်။ စွဲလမ်းသည်။','“သၟိၚ်တံညးဂမၠိုၚ်ဂှ် ပ္ဍဲကၟိန်ဍုၚ်ဂှ် ထၞေန်တဴစိုတ်အိုတ်ရ။” (ဇ—၄၉၆။ အစွောံ။) = “မင်းအ ပေါင်းတို့သည် တိုင်းနိုင်ငံ­ တပ်မက်မောကြကုန်၏။” || “သေဋ္ဌဳဗာရာဏသဳမွဲ ပ္ဍဲဇရေၚ်ကြုၚ်ဂှ် ဒြပ်ပန်စှ်ောကိုတ်တိုပ်လဝ် ဟိုတ်မထနေန်စိုတ်ကဵုဒြပ် ချိုတ်ဒှ်ဇြုံ ဒၟံၚ်ပ္ဍဲလတူဒြပ်ဂှ်ရ။” (ဇ—၇၃။ အစွောံ။) = “ဗာရာဏသီပြည်­နေသော တယောက်သောသူဌေးသည် မြစ်နား­ ကုဋေလေးဆယ်သော ဥစ္စာကိုမြှုပ်၍ သေသည်ရှိသော် တပ်စွန်းခြင်းကြောင့် ဥစ္စာအပြင်­ မြွေ၏အဖြစ်ဖြင့် ဖြစ်၏။” (ညောင်ကန်) || “ဒြာဲကျာဂှ် ကၠုၚ်စဒးကၞုၚ်ကၟတ်ဂှ်တုဲ ထနေန်စိုတ်ပ္ဍဲရသာရီုဂှ်တုဲ ဋ္ဌာန်သ္အာၚ်ဟွံအာဂၠာဲစရ။ ကၟတ်ညးလေတ်လဝ်ဍာ်သာဲဂှ် ရိုဟ်ဟ်တ္ၚဲကၠုၚ်စဒၟံၚ်ရ။” (ဇ—၁၄။ အစွောံ။) = “ထိုသမင်သည် လာလတ်၍ ပျားလူးမြက်ကို စားမိသည်ရှိသော် ရသာရုံ­တပ်မက်သည်ဖြစ်၍ တစ်ပါးသောအရပ်သို့ အစာရှာမသွားမူ၍ ထိုပျားလူးမြက်ကိုသာ နေ့တိုင်းနေ့တိုင်း လာ၍စား၏။” || “ကလော်ဗြဴမွဲဂှ် ဍေံကျိုၚ်ဂေါဝ်ဒၟံၚ်၊ ဗၠာဲသၟိၚ်မွဲဂှ် ထဏေန်စိုတ်ရုပ်ဍေံတုဲ ဒီုဒၟံၚ်ဖဴကလော်ဗြဴ ဂှ်ရ၊ ဒးကာလဗတံ ကလော်ဗြဴစကၠေံရ။” (ဇ—၉၆။ အစွောံ။) = “တစ်ယောက်သောဘီလူးမသည် လှပစွာဆင်ယင်လျက်နေ၏၊ တစ်ယောက်သောမင်းချင်းယောကျာ်းသည် ရူပါရုံ­ တပ်စွန်းသည်ဖြစ်၍ ဘီလူးမနှင့်တကွ အိပ်စက်နားနေ၏၊ ညဉ့်သို့ရောက်သောအခါ ဘီလူးမက စားပစ်လိုက်၏။”')
,(6243,3,4,'ပြင်းစွာတပ်စွန်းသည်။ အလွန်အမင်းစွဲလမ်းသည်။','(သၟိၚ်) ထဏေန်စိုတ်ဗိုန်အာ ပ္ဍဲသၟတ်ဗြဴတုဲ “နဥပ္ပါယ်မွဲအဲသ္ပတုဲ ဂစိုတ်ကၠေံတြုံဍေံတုဲ အဲသ္ဂောံ သၟတ်ဗြဴရောၚ်” သၟိၚ်ချပ်။ (ဇ—၁၉၄။ အစွောံ။) = မင်းသည် ထိုမိန်းမပျို­ အလွန်အမင်းတပ် စွန်းသည်ဖြစ်၍ “တစ်ခုသောဥပ္ပါယ်ဖြင့် သူ့လင်ကိုသတ်၍ ဤမိန်းမပျိုကို ငါရအံ့” ဟုကြံ၏။')
,(6244,3,4,'၁။ ကပ်ငြိသည်။ စွဲကပ်သည်။','“ယဲဝေဒနာဒစိတ်စှ်ောတြဴ လ္ပကဵုထၞေန်စေန်စပ် ပ္ဍဲခန္ဓသန္ထာန်ညိ။” = “ကိုးဆယ့်ခြောက်ပါးသော ရောဂါဝေဒနာများ ခန္ဓာ ကိုယ်­ မကပ်ငြိပါစေနှင့်။”')
,(6244,3,4,'၂။ တတ်မက်သည်။ တပ်စွန်းသည်။ စွဲလမ်းသည်။','“ထဏေန် စေန်စပ်ဒၟံၚ်ကဵုကောန်ဇာတ်မ္ဂး ချိုတ်အာအပါဲရောၚ်။” = “သားသမီးများကို စွဲလမ်းနေလျှင် သေသော် အပါယ်လားလိမ့်မည်။” || “ဣသိဍောတ်ဂှ် မိၚ်ဒလောအ်ဗ္တောန်မဂှ်တုဲ ကလေၚ်ကလေအ် ထောံစိုတ် မထၞေန်စေန်စပ်မံၚ်ကဵုဗြဴဂှ်ရ။” (ဇ—၅၂၆။ အစွောံ။) = “ထိုရသေ့ငယ်သည် ဖခင်၏ အဆုံးအမစကားကို ကြားသည်ရှိသော် ထိုမိန်းမ­တပ်စွန်းစွဲလမ်းနေသောစိတ်ကို ပြန်လည်ဖြေ ဖျောက်ပစ်လိုက်၏။”')
,(6245,3,4,'၁။ ကပ်ငြိသည်။ ငြိတင်သည်။','‘ဍာ်ဟွံစပ်ထဏေန် ပ္ဍဲသၠဒကှ် ရ။’ = ‘ကြာရွက်­ ရေမငြိတင်ပါ။’')
,(6245,3,4,'၂။ တပ်စွန်းသည်။ စွဲလမ်းသည်။','“ဒြာဲကၟက်ဂှ် ဟိုတ် စိုတ်မထနေန်စပ်အာတုဲ ဂကောံဒြာဲဗြဴဝုတ်ဂှ် ဒၟံၚ်တဴရ။” (၅၅ဝ။ ဇ—၁၃။ ပ—၄၆။ အစွောံ။) = “သမင်ဖိုသည် သမင်မငယ်­ စိတ်တပ်စွန်းသွား၍ ထိုသမင်မနှင့်တကွ နေ၏။”')
,(6245,3,4,'၃။ (အနာရောဂါစသည်) ကူးစက်သည်။ ကပ်ငြိသည်။','“မံၚ်သ္အးသ္အးဇ္ၚးဇ္ၚးမ္ဂး ယဲဘဲထဏေန်စပ်ဟွံလောဲရ။” = “သန့်သန့်ရှင်းရှင်းနေထိုင်လျှင် ရောဂါကူးစက်ကပ်ငြိရန်မလွယ်ပါ။”')
,(6246,3,4,'ချစ်သည်။ ချစ်ခြင်းဖြစ်ပေါ်သည်။ ချစ်နှစ် သက်သည်။','“ယွံကောန်၊ မၞိဟ်ဒက်မိတ်မဟွံဗိုန် မတုပ်တဴရဴလွံက်မိတ်ဂှ် ဍေံမၞုံစိုတ်မပြဟ် မတုပ် တဴရဴစိုတ်ကၞုဲ မဟွံဂွံဗစာရဏာ ဍေံမၞုံစိုတ်မထဏေန်ဇြဟာန် မွဲချိုန်မွဲခဏဂှ် မၞိဟ်မဖှ်သာ်ဂှ် မၞးလ္ပ သိပ်ဂၠိပ်ခစညိကောန်။” (ဇ—၃၄၈။ အစွောံ။) = “ချစ်သား၊ နနွင်းဆိုးရည်ကဲ့သို့ မမြဲသောစိတ် ရှိသော၊ မျောက်ကဲ့သို့မဆင်မခြင် လျင်မြန်သောစိတ်ရှိသော၊ တစ်ခဏမျှ ချစ်ခြင်းဖြစ်တတ်သော ဤကဲ့သို့သောလူကို မမှီဝဲလေလင့်။”')
,(6247,3,4,'မကောင်းဆိုးဝါးတစ္ဆေမှင်စာတို့၏ ပြုစားခြင်း ဖမ်းစားခြင်းခံရသည်။',NULL)
,(6248,3,16,'','‘ထၞဟ်’ ရှု။')
,(6249,3,4,'၁။ ရိုသေလေးမြတ်သည်။ အလေးအမြတ်ပြုသည်။ ကြည်ညိုလေးစားသည်။','“မြိမြန် ကၠောန်ၜိုတ်သဳသန် သဳကၠဳဝဳပရာမိကဵုမ ထဒၟရှ်ေသှ်ေအဲပရဲလၟိုန်။” (ဇ—ဝေသန္တဝ်။ အစွောံ။) = “အမိအဖတို့ကို လုပ်ကိုင်ကျွေးမွေး ပြုစုစောင့်ရှောက်၍ အစဉ်အမြဲ ရိုသေလေးမြတ် ကြည်ညို ဦးညွတ်၏။”')
,(6249,3,4,'၂။ လှိုက်လှဲပျူငှာစွာ ဆက်ဆံသည်။ ဝမ်းသာအယ်လဲကြိုဆိုသည်။ ဝမ်းမြောက် လိုလားစွာစောင့်ကြိုသည်။','“ဗြဴဂှ်သၠိုက်ကၠေံဇနိက်တုဲ မၠာ်ၚဳရံၚ်(ညာတ်ခမဳဂှ်)တုဲ ‘သြ—မၞးတံ၊ ဣ တကောန်ၚာ်ပိုဲရောၚ်သွံ’ ဂးတုဲ ထဒၟတိတ်အာဂိုၚ်ကေတ်ဗဗေၚ်တုဲ က္ညပၠောပ်ဏာသ္ၚိရ။”(ဇ—၄၂၃။ အစွောံ။) = “ထိုမိန်းမသည် တင်းတိမ်ကိုပင့်၍ ကြည့်လတ်သော် ထိုရဟန်းကိုမြင်၍ ‘သြော်အ သင်တို့၊ ငါတို့၏ကလေးအဖေပါလား’ ဟုဆိုကာ ဝမ်းသာအယ်လဲထွက်ကြို၍ သပိတ်ကိုယူ၍ အိမ်ထဲသို့ ပင့်ဆောင်၏။” || “ကၠဵုဂှ် ညာတ်ပုၚ်ကလောအ် ထဒၟကၠုၚ်။” (ဇ—မဟောဟ်သဓ။ အစွောံ။) = “ထိုခွေးသည် ထမင်းတုံးကိုမြင်သည်ရှိသော် ဝမ်းမြောက်လိုလားစွာ ကြိုလျက်လာ၏။”')
,(6250,3,4,'၁။ လှိုက်လှဲပျူငှာစွာ ဆက်ဆံသည်။ —ကြိုဆိုသည်။ လိုလားစွာတမ်းတစောင့်ကြိုသည်။','“လၟကၠုၚ်စိုပ်သ္ၚိသၟိၚ်ဂှ်တုဲ ထ္ၜးကဵုသၟိၚ်ရ။ သၟိၚ်ညာတ်(သၟိၚ်ၜိုပ်ထဝ်)တုဲ သၟိၚ်မိပ်စိုတ်အိုဟ် တၟိုဟ်စိုတ်တုဲ သၟိၚ်ပထဒၟဖဳဒွါ ကုသၟိၚ်ၜိုပ်ထဝ်ဂှ်ရ။”(ဇ—၅၃၃။ အစွောံ။) = “မုဆိုးသည် မင်း အိမ်သို့ရောက်၍ ရွှေဟင်္သာမင်းကို မင်းအားပြ၏။ မင်းသည်မြင်၍ ရွှေဟင်္သာမင်းကို လှိုက်လှဲပျူငှာ ဝမ်းသာအယ်လဲကြိုဆို၏။” || “(သၟိၚ်တ္ၚဲက္တဵုဒှ်တုဲ) ဇန်တံညာတ်ဇဳ၊ မိပ်စိုတ်ဖဳဒွါ။ ဟိုတ်ပျးကဵု ဂၟံၚ်၊ စိုတ်သတ်သံၚ်သာ။ ပ္ညပ်လဝ်နာမ၊ သူရိယျကၠာ။ သက်သမိၚ်ပၠန်၊ ဂၠုဗဒန်အာ။ အဲအဲညးညး၊ တဟးသိၚ်သာ။ ကၠုၚ်ကောံမံၚ်ရော၊ ဟီုစောဒနာ။ မူဂှ်မၞုံလျး၊ သ္တိုန်ပၠန်သ္ဂးဟာ။ ပ္ဍဲမစမဳ၊ ထဒၟဖဳ ဒွါ။ ချိုန်ဂှ်ညာတ်ပၠန်၊ လျးစက်စန္ဒြာ။” (လိက်ဗောဓိသတ်စှ်။ တၠဂုဏ်အ္စာပဏ္ဍိတ။) = “(နေမင်းဖြစ်ပေါ်လာရာ) လူအပေါင်းအစုံ မြင်ကြရကုန်သော် ဝမ်းမြောက်ရွှင်လန်းရှိကြကုန်၏။ သတ္တ ဝါအပေါင်း၏စိတ်ကို ရဲရင့်ထွန်းလင်းစေသဖြင့် သူရိယျဟူ၍ အမည်ပေးကုန်၏။ ထိုနောက်­ မှောင်မိုက်၍ကွယ်ပြန်လေသော် သူသူငါငါ စိတ်ထိခိုက်ကုန်လျက် စုရုံးလာကြကုန်၍ အပြစ်ဆို ကြလေ၏။ အလင်းရှိသော အဘယ်အရာသည် တက်လာပြန်အံ့နည်းဟု လိုလားစွာတမ်းတစောင့် ကြိုနေကြစဉ် လမင်းစန္ဒာ၏အလင်းရောင်ကို ထိုခဏ­ မြင်ကြရပြန်ကုန်၏။”')
,(6250,3,4,'၂။ ကြင်နာယု ယသည်။','“ခနှောဝ်တြုံဗြဴၜါဂှ် မွဲဟာန်ကေုာံရၚ်သ္ကအ် ဇကုကဵုဇကုဂှ် ဗန်ကအ်ရၚ်သ္ကအ်တုဲ ဆုၚ်တဴရၚ်သ္ကအ်တုဲ သီုကဵုမထဒၟဖဳဒွါ ရိုဟ်ရေၚ်ဂၠာဲဟီုအာ ယာံတဴရ။” (ဇ—၅ဝ၄။ အစွောံ။) = “နှစ်ခုကုန်သောကိနနရာဖို၊မတို့သည် အချင်းချင်း လည်ဖက်နမ်းရှုပ်၍ ကြင်နာယုယ စွာ တတွတ်တွတ်ဆိုမြည်တမ်းလျက် ငိုကြွေးကုန်၏။”')
,(6251,3,4,'‘ထၞိက်’ ရှု။',NULL)
,(6252,3,4,'(အနာ၊ နားစသည်ကို ဂွမ်းဖတ်၊ ကြက်တောင်စသည်ဖြင့်)ကျပ်သည်။','‘ထပူကတောဝ် ကဵုသၞေၚ်စာၚ်။’ = ‘ကြက်တောင်ဖြင့် နားကျပ်သည်။’')
,(6253,3,4,'(အချွန်ဖြင့်) ထိုးသည်။','ထပက်ကဵုၜုန် = ဓါးနှင့်ထိုးသည်။ || ထပက်ဂဥုဲ = ဆေးထိုးသည်။')
,(6254,3,3,'ယုတ်မာသော။ ကောက်ကျစ်သော။','‘ဗြဴဒမိက်မယုတ်မာထမုန်ထပက်ကာ။’ (ဇ—၅၃၆။ အစွောံ။) = ‘လိမ်လည်လှည့်ပတ် ယုတ်မာကောက်ကျစ်သောမိန်းမ။’')
,(6255,3,1,'ဆေးထိုးသည်။',NULL)
,(6256,3,4,'ကလိထိုးသည်။ (ချိုင်းကြား၊ ခါးကြားကို ယားကျိကျိဖြစ်အောင် လက်ချောင်းဖြင့်ထိုးကစားသည်။)','ပွမထပက်စံက်လေက် နကဵုလပုဟ်တဲ = လက်ချောင်းဖြင့် ကလိထိုးခြင်း။')
,(6257,3,4,'ခြေထိုးသည်။ ကုန်းချောသည်။',NULL)
,(6258,3,4,'တဲထိုးသည်။ တဲဆောက်သည်။',NULL)
,(6259,3,4,'ကျပ်ပူတိုက်သည်။ ကျပ်ထုပ်ထိုးသည်။',NULL)
,(6260,3,4,'သင်္ကန်း­ ရဟန်းနှင့်အပ်စပ်အောင် (အစက်အပြောက်) ကပ္ပဗိန္ဒုထိုးသည်။ (ပါဠိ—ကပ္ပဗိန္ဒု)',NULL)
,(6261,3,4,'ထိုးကွင်းမင်ကြောင်ထိုးသည်။',NULL)
,(6262,3,4,'တိုးသည်။','“ထပါ်လုပ်အကြာမၞိဟ်ဂမၠိုၚ်။” = “လူအများကြား တိုးဝင်သည်။” || ထပါ်တိတ် = တိုးထွက်သည်။')
,(6263,3,4,'ထွက်ပြေးသည်။',NULL)
,(6264,3,4,'(ထမင်းစသည်) ပျော့လွန်းသည်။','“ပုၚ်ထပေက်အာရ။” = “ထမင်းပျော့သွားသည်။”')
,(6265,3,1,'၁။ ဖြတ်ပိုင်းစာအုပ်။',NULL)
,(6265,3,4,'ဖြတ်သည်။','ထပိုတ်အရက် = အရက်ဖြတ်သည်။ || ထပိုတ်ၜံက် = ဆေးလိပ်ဖြတ်သည်။ || ဂဥုဲထပိုတ်ဇွဟ် = အဖျားဖြတ်ဆေး။')
,(6265,3,1,'၂။ ပုရပိုက်။','ထပိုတ်ထဝ် = ရွှေပုရပိုက်။ ရွှေပြား။ || ‘ဗပိုတ်’ ရှု။')
,(6266,3,4,'(နို့စို့ကလေးအား) နို့ဖြတ်သည်။',NULL)
,(6267,3,4,'သေခန်းဖြတ်သည်။ သေခန်းရှင်ခန်းဖြတ်သည်။',NULL)
,(6268,3,4,'သံယောဇဉ်ဖြတ်သည်။',NULL)
,(6269,3,4,'အဆက်ဖြတ်သည်။ အဆက်အသွယ်ဖြတ်သည်။',NULL)
,(6270,3,4,'ပုန်ကန်သည်။',NULL)
,(6271,3,4,'ပုန်ကန်ထကြွသည်။',NULL)
,(6272,3,4,'(ထမင်းမချက်မီ) ဆန်ဆေးသည်။',NULL)
,(6273,3,1,'ကိုရင်။ ရှင်သာမဏေ။',NULL)
,(6274,3,1,'၁။ တံပိုး။ (မှုတ်စရာတစ်မျိုး)',NULL)
,(6274,3,1,'၂။ ထုံး။',NULL)
,(6275,3,16,'ခုနစ်။','ထပှ်စှ်ော = ခုနစ်ဆယ် || ထပှ်လ္ၚီ = ခုနစ်ထောင်။')
,(6276,3,4,'‘သပြိပ်’ ရှု။',NULL)
,(6277,3,4,'ဆုံသည်။','ထဗဆဵု = တွေ့ဆုံသည်။ || ‘ဂဗ’ ရှု။')
,(6278,3,1,'ဖုံမှုန့်။',NULL)
,(6279,3,4,'ခုတ်လှဲသည်။','ဂဗိုၚ်တၞံဆု = သစ်ပင်ခုတ်လှဲသည်။')
,(6280,3,4,'သွားလာဖန်များ၍ လမ်းကြောင်းနေရာ ထင်ရှားသည်။ လမ်းဖုန်သည်။','“ဂၠံၚ်အာ ကွာန်တၟိဂှ် ထဗုတ်ဒၟံၚ်ရ။” = “ရွာသစ်သို့သွားသောလမ်းသည် လမ်းဖုန်နေသည်။”')
,(6281,3,1,'စည်။ ပတ်မ။',NULL)
,(6282,3,4,'လိပ်သည်။','ထမူဒကဝ် = ဖျာလိပ်သည်။ || ထမူၜံက် = ဆေးလိပ်လိပ်သည်။')
,(6282,3,9,'အလိပ်။','ဒကဝ်ၜါထမူ = ဖျာနှစ်လိပ်')
,(6282,3,4,'လိပ်သည်။','ဒကဝ်ပိထမူ = ဖျာသုံးလိပ်။')
,(6283,3,4,'ဟပ်သည်။ ပါးစပ်၊ နှုတ်သီးဖြင့် ဖမ်းကိုက်သည်။','“ကၠဵုထၟက်စဒၟံၚ်ပုၚ်ရ။” = “ခွေးသည် ထမင်းကို ဟပ်ပြီးစားနေသည်။” || “ညံၚ်ကၠိက်ကဵုကၠိက် မထမက်တဴပ္ဍဲအသုဘတုဲ သၟဟ်တုဲ မဟွံဂွံက္ဍုဟ်ရၚ်သ္ကအ်ရ။” (ဇ—၁၅၈။ အစွောံ။) = “ဝက်နှင့်ဝက်တို့သည် မစင်­အတူ ဟပ်၍ တူမျှကုန်သဖြင့် အချင်းချင်းမရွံမုန်းကုန်။”')
,(6284,3,1,'ကောင်းခြင်း။','“ဓဝ်သဳလဂှ် မဒှ်ထမှိက်ရောၚ်။ ပ္ဍဲလိုက်ဝွံ ဓဝ်သဳလမွဲ ပြဲလောန်ရောၚ်။” (ဇ—၂၉ဝ။ အစွောံ။) = “လောက­ သီလသည်သာလျှင် ကောင်းသတတ်။ သီလသည်မြတ်သတတ်။” (ညောင်ကန်)')
,(6284,3,3,'ကောင်းသော။','“ယြဴပူဂဵုမွဲ ပ္တုဲလဝ်ကုသဵုပွ ထၟိက်တုဲဂှ် အာဲကၟာဲကုသဵုထၟိက်ဂှ် ဍေံဂွံစသိုၚ်ရ။” (ဇ—၃၅၃။ အစွောံ။) = “ကုသိုလ်ကောင်းမှုကို ပြုထားသောသူသည် ကုသိုလ်ကောင်းမှု၏ ကောင်းသောအကျိုးကို ခံစားရ၏။” || “ဗြဴဂှ်တုန် ပတွဵုနူညးမဝေတ်လဝ်တုဲဂှ် ကေုာံဓဝ်ဗြဴထမိက် ဍေံမစိုန်သကီုဂှ်ဒှ်တုဲ တြုံတလသ္ၚိဂှ်လေဝ်ကီု ခါံသဳ တြုံဂှ်လေဝ်ကီု ကောန်တြုံဂှ်လေဝ်ကီု မြိမြန်တဴရ။” (ဇ—၄၄၆။ အစွောံ။) = “ထိုမိန်းမသည် ဆုံးမအပ်ပြီးသည်မှစ၍ မိန်းမကောင်းတို့၏တရားနှင့် ပြည့်စုံသည်ဖြစ်၍ လင်ကိုလည်းကောင်း ယောက္ခမကိုလည်းကောင်း သားကိုလည်းကောင်း လုပ်ကျွေးပြုစု၏။” ||“မိတ်ထမှိက်မ္ဂး ပြဲ ယုတ်ဟွံဂပ်ဂဝ်သ္ဂး။” (ဇ—၁၂၁။ အစွောံ။) = “မိတ်ဆွေကောင်းမည်သည်ကို အယုတ်အမြတ်မခွဲခြားရာ။” || “န်ဂလာန်ထမိက်ဂှ်ဟေၚ် ဂပ်ဂဝ်ဟီု။” (ဇ—၈၈။ အစွောံ။) = “ကောင်းသောစ ကားကိုသာလျှင် ဆိုရာ၏။” (ညောင်ကန်)')
,(6285,3,1,'(မိန်းမတို့၏) ကောင်းခြင်းငါးဖြာ။','“ဇနပဒ ကလျာဏဳဂှ် မနွံကဵုစရာဲရုပ် မဍိုက်ပေၚ်တဴထမှိက်မသုန်သာ်ရောၚ်။ ထမှိက်စၞာံဇကု ထမှိက်ဖျုန် ထမှိက်လတေၚ် ထမှိက်ဇုတ် ထမှိက်အဝဲ။” (ဇ—၉၆။ အစွောံ။) = “ဇနပဒကလျာဏီသည် အ လွန်တင့်တယ်သော ရုပ်အဆင်းရှိ၏။ အရေ၏ကောင်းခြင်း၊ အသား၏ကောင်းခြင်း၊ အကြော၏ ကောင်းခြင်း၊ အရိုး၏ကောင်းခြင်း၊ အရွယ်၏ကောင်းခြင်းတည်းဟူသော ကောင်းခြင်းငါးဖြာနှင့် ပြည့်စုံ၏။” || “လက်သန်ထမိက်မသုန်သာ် မတွံဂး ထမိက်စၞာံဇကု၊ ထမိက်ဖျုန်၊ ထမိက်သော်၊ ထမိက်ေၚက်၊ ထမိက်အဝဲ မဟွံဂွံဗျုညံၚ်ဝုတ်စှ်တြဴသၞာံကီု။” (ဇ—၃၈၇။ အစွောံ။) = (မှတ်ချက်။ အကြော၏ကောင်းခြင်း၊ အရိုး၏ကောင်းခြင်းနေရာ­ ဆံ၏ကောင်းခြင်း၊ သွား၏ကောင်းခြင်းဟူ၍ လာသည်။ မြန်မာအဘိဓါန်အကျဉ်းချုပ်­ ၁) ဆံ၏ကောင်းခြင်း၊ ၂) အသား၏ကောင်းခြင်း၊ ၃) အရိုး၏ကောင်းခြင်း၊ ၄) အရေ၏ကောင်းခြင်း၊ ၅) အရွယ်၏ကောင်းခြင်းဟူ၍ ဖော်ပြသည်။)')
,(6286,3,4,'ထောင်းသည်။','ထမုက်ဖရံက် = ငပိထောင်းသည်။')
,(6287,3,1,'အခေါင်းပေါက်။','ထမော်ဆု = သစ်ခေါင်း။ || ထမော်တၟအ် = လိုဏ်ဂူ။')
,(6288,3,1,'ပါးစောင်။ မေး။','ထမၚ်ချိုတ် = မေးခိုင်သည်။ ပါးစောင်ညောင်းသည်။ || ထမၚ်ဂုဟ် = ပါးချိတ်ရောင်သည်။ || “ယွံမၞးတံ၊ ဍာ်မှာသၟိတ်ဝွံဂှ် ပိုဲဂၜံထောံကၠေံဍာ်ဂှ် ဇုတ်ထမၚ်ပိုဲ လေဝ် ချိုတ်ကွိုၚ်အာရ။ ——” ခဍာ်ဂမၠိုၚ်ဂး။ (ဇ—၁၄၆။ အစွောံ။) = “အိုကျီးတို့၊ ဤသမုဒြာ ရေကို ငါတို့သည် ခံတွင်းဖြင့်ငုံ၍ ထုတ်သည်ရှိသော် ငါတို့၏မေးရိုးတို့သည်လည်း ညောင်းကုန် ၏။ ——” ဟုကျီးတို့ဆို၏။')
,(6289,3,1,'ခေါင်းပေါင်း။ ဦးရစ်။ (ပါဠိ—ဝေဋ္ဌန)',NULL)
,(6289,3,1,'ခေါင်းပေါင်းပေါင်းသည်။','ထမိၚ် လဝ်က္ဍိုပ် = ခေါင်းပေါင်းပေါင်းထားသည်။ || ‘ခၟိၚ်’ ဟုလည်းရေးသည်။')
,(6290,3,4,'ရုပ်ရည်ဆင်တူသည်။','“သၟတ်ဗြဴဂှ် ရုပ်သာ်ထမုၚ်ဒၟံၚ်ကဵုၝဲအဲရ။” = “ထိုသူငယ်မသည် ကျွန်တော့်အစ်မနှင့် ရုပ်ချင်းဆင်တူသည်။”')
,(6291,3,1,'အပေါက်။',NULL)
,(6292,3,1,'နားပေါက်။','“ကၞုဲမအန်တဴကဵုသဳလမွဲဂှ် ဍေံကၠုၚ်ပ္ဍဲထ မောၚ်ကတောဝ်ဗောဓိသတ် (ဣသိ) ဂှ် ပွမပအာမေထုန်ဂှ် ဍေံပရ။” (ဇ—၂၇၃။ အစွောံ။) = “တခုသောသီလမရှိသော ပြစ်မှားတတ်သောမျောက်သည် လာလတ်၍ (ဘုရားလောင်း၏) နားပေါက်တို့­ အင်္ဂါဇာတ်ကို သွင်းသောအမှုကို ပြု၏။” (ညောင်ကန်)')
,(6293,3,1,'(ဝမ်းဗိုက်ရှိ) ချက်။','“နကံမဖျုၚ်လဝ်ဂျိဂှ် လၟဗလးပန်ပတိုန်ဏာ သၟိၚ်စိၚ်ဆဒ္ဒန် ဒးနူထမောၚ်ဂြိုဟ် ကၠိုဟ်သာတ်တိုန်အာဒဵုစး။” (ဇ—၅၁၄။ အစွောံ။) = “ဆဒ္ဒန်ဆင်မင်းကို ဆိပ်လူးမြှားဖြင့် မုဆိုးပစ်တင်လိုက်ရာ ချက်မှဖောက်ထွင်း၍ ကျောက်ကုန်းသို့တိုင် ဖောက်ထွက်သွား၏။”')
,(6294,3,9,'အဆုပ်။','ပုၚ်မွဲထမှတ် = ထမင်းတစ်ဆုပ်။ || “ဓဇဲတံတုန်လေဝ် ကာလမဟာပ်ပုၚ် ညးမွဲမွဲ ပုၚ်မွဲမွဲထမှတ်၊ ညးမသုန်ကၠံ ပုၚ်မသုန်ကၠံထမှတ် က္ၜတ်ကဵုစိၚ်ရ။” (ဇ—၁၅၆။ အစွောံ။) = “လက်သမားတို့သည်လည်း ထိုဆင်အား ထမင်းစားသောအခါ­ တဆုပ်တဆုပ်စီသော ထမင်းဆုပ်တို့ကို ပြုကုန်၍ ငါးရာကုန်သောထမင်းဆုပ်တို့ကို ပေးကုန်၏။” (ညောင်ကန်)')
,(6294,3,4,'အဆုပ်ဖြစ်အောင်လုပ်သည်။','ထမှတ်ကမၠေၚ် = ကောက်ညှင်းကို အဆုပ်ဖြစ်အောင်လုပ်သည်။')
,(6295,3,1,'အနားအစွန်း။','ထမန်ပါၚ် = နှုတ်ခမ်း။')
,(6296,3,1,'လိမ်လည်ခြင်း။ မဟုတ်မမှန်ဆိုခြင်း။ မုသားဆိုခြင်း။ (ပါဠိ—မုသာဝါဒ)','“ပူဂဵု ထမုန်မုသာစၞာဲတံဂှ် နဂလာန်မစၟတ်ဂှ် သၟိၚ်နာဲပိုဲကေတ်ဇၞးရောၚ်။” (ဇ—၁၅၁။ အစွောံ။) = “ငါတို့အရှင်မင်းသည် လိမ်လည်စဉ်းလဲသောသူတို့ကို မှန်သောစကားဖြင့် အနိုင်ယူ၏။”')
,(6296,3,4,'လိမ်လည်သည်။ မုသားဆိုသည်။','“အဲမဒးထမုန်စုတ်ကဵုဒေဝတဴတုဲ လၟုဟ်ဝွံဂှ် ပ္ဍဲက္ဍိုပ်အဲဝွံ ဇလပသဲစင်က္ဍိုပ်အဲလောန်ဗၞတ်ရောၚ်” ဗမၞးစၞာဲဂး။ (ဇ—၃၂၆။ အစွောံ။) = “ငါသည် နတ်သားတို့ကို လိမ်လည်မိ၍ ယခုအခါ ငါ့ဦးခေါင်း­ အလွန်အမင်း သံဆူးစူးသကဲ့သို့ရှိ၏” ဟုပုဏ္ဏားစဉ်း လဲဆို၏။ || “မၞိဟ်ထမုန်မုသာ ညံၚ်ဗမၞးဂှ် အဲပ္ကတ်ဟွံဒှ်ရ” ဗောဓိသတ်ဂး။ (ဇ—၄၇၄။ အစွောံ။) = “ထိုပုဏ္ဏားကဲ့သို့ လိမ်လည်မုသားဆိုသူကို ငါအတတ်သင်ပေးရန် မဖြစ်နိုင်ပါ” ဟုဘုရားလောင်းဆို၏။ || “ဂလာန်ကၠဵုထမုန် မၞးပ္တေဟ်ဟာ။” (ဇ—၁၁၃။ အစွောံ။) = “လိမ်လည်သော မြေခွေးစကားကို သင်ယုံသလော။”')
,(6297,3,16,'‘ထမုန်’ နှင့်အတူတူ။','“ဒ္ဂေတ်ထမုန်စၞာဲမဒးပတုဲ ဒေဝဒတ်မဒးစိန် ဒၟံၚ် ပ္ဍဲနရက်အဝိက်—။” (ဇ—၁၁၃။ အစွောံ။) = “လိမ်လည်ကောက်ကျစ်သော အကျင့်ကိုကျင့် သဖြင့် ဒေဝဒတ်သည် အဝီစိငရဲ­ ပူလောင်ခံစားနေရ၏။”')
,(6298,3,16,'‘ထမုန်’ နှင့်အတူတူ။','‘ဂလာန်မုသာထမုန်တၠန်’ (ဇ—၅၂၁။ အစွောံ။) = ‘လိမ်လည်သောမုသားစကား။’')
,(6299,3,1,'မေး။','သော်ထမိပ် = မုတ်ဆိတ်မွေး။')
,(6300,3,1,'(ပန်း)အငုံ။',NULL)
,(6300,3,4,'ငုံသည်။','“တၞံပ္ကဴမၠဵုပ္ဍဲကၠအ်ပိုဲဂှ် ခၟောမ်ဒၟံၚ်ရ” = “ကျွန်တော်တို့ခြံမှ စပယ်ပင်သည် ငုံနေပြီ။” || ‘ခၟောမ်’ ရှု။')
,(6301,3,1,'အိုး။','ထၟာဲပုၚ် = ထမင်းအိုး။ || ထမာဲတိ = မြေအိုး။ || ထၟာဲသၠုဲ = ကြေးအိုး။ || ထမာဲဒါန် = ဒန်အိုး။ သတ္တုအိုး။ || “ကေတ်ဖျေံဏာ သီုထမှာဲပုၚ်သွဂှ်တုဲ—။” (ဇ— ၂၈၄။ အစွောံ။) = “ထမင်းအိုးဟင်းအိုးတို့ကိုပါ ယူချသွားပြီးလျှင်—။”')
,(6302,3,1,'အဝကျယ်သောမြေအိုး။',NULL)
,(6303,3,1,'ထွေးခံ။ ထွေးအင်။ ပြတို့။ (ပါဠိ—ခေဠမလ္လက)','‘ထမာဲတဲ’ နှင့်အတူတူ။ (ဂစှ် ကသှ် = တံတွေး)')
,(6304,3,1,'အလေးအပေါ့သွားရန်အိုး။ နောက်ဖေးအိုး။',NULL)
,(6305,3,1,'ရေမြွာ။ (သန္ဓေသားကို ပတ်ဖွဲ့တည်ရှိနေသောရေအိတ်။)',NULL)
,(6306,3,1,'ထွေးခံ။ ထွေးအင်။',NULL)
,(6307,3,1,'သတ္တုအိုး။',NULL)
,(6308,3,4,'ဖြည်းညှင်းစွာလှုပ်ရှားသည်။','ကျာထရဳ = လေပြည်တိုက်ခတ်သည်။')
,(6309,3,4,'စပါးလှေ့သည်။',NULL)
,(6310,3,4,'၁။ ရှူရှိုက်သည်။','ထရောတ်ဂဥုဲနုဟ် = နှာရှူဆေးမှုန့်ကို ရှူရှိုက်သည်။')
,(6310,3,4,'၂။ စုပ်သောက်သည်။','ထရောတ်သုၚ်ဍာ်ဂမ္တဴ = ရေနွေးကို စုပ်သောက်သည်။')
,(6310,3,9,'(ရေ)တစ်ကျိုက်။','ဍာ်မွဲထရောတ် = ရေတစ်ကျိုက်။ ရေတစ်ငုံ။ (ပါဠိ—ဂဏ္ဍူသ)')
,(6311,3,1,'စရန်ငွေ။','“ဗၞိက်ပိုဲဝွံ မၞးတအ်ဟွံဂွံရ၊ တေံညးဗၞိက်ဇၞော် မဒၟံၚ်ပ္ဍဲဇနိက်ဂှ် ကဵုလဝ်ထရမ် ကဵုပိုဲတုဲရ။” (ဇ—၄။ အစွောံ။) = “သင်တို့သည် ငါတို့၏ကုန်ပစ္စည်းကို မရကုန်လတ္တံ့၊ ထိုတင်း တိမ်အတွင်း­နေသော ကုန်သည်ကြီးသည် ငါတို့ကို စရန်ပေးထားပြီးပြီ။”')
,(6312,3,1,'ရွှံ့ညွန်။','‘သရီု’ ရှု။')
,(6313,3,4,'ခုန်သည်။','‘စလာ်’ ရှု။')
,(6314,3,4,'ကျွံသည်။ ကြမ်းကျွံသည်။','“(ထေရ်ဗျုဂှ်) ဒြေပ်လောပ်အာ သ္ၚိဍာ်တရေံ သမ်အိုဟ်မွဲ ထလိုၚ်ဗၠုက်စှ်ေအာ ဂၠက်ဂဗှ်ေဒၟံၚ် ပ္ဍဲအသုဘရ။” (ဇ—၁၅၃။ အစွောံ။) = “ရဟန်း အိုသည် ဆွေးသောအိမ်သာဟောင်းတစ်ခုထဲသို့ ပြေးဝင်သွားသည်ရှိသော် ကြမ်းကျွံ၍ မစင်တွင်း ထဲသို့ကျသွားရာ မစင်အလူးလူး လိမ်းကျံလျက်တည်၏။” || “ညံၚ်ဇၟူတၠအစောံ ဟွံပ္တေဟ်ဇိုၚ်ပန် တုဲ နလပှ်ဖျောန်ဏာဂတ စံၜတ်တုဲမကွာ်ဂး ဇၟူဂှ် ဟွံသလိုၚ်ဟွံတဆူရောၚ်။” (ဇ—ဝိဓုရ။ အစွောံ။) = “အစွမ်းအားရှင်ဖြစ်သော ဆင်ပြောင်ကြီးသည် အခြေလေးချောင်းတို့ကို မယုံမူ၍ နှာ မောင်းရှေ့သွား လမ်းညွှန်ပြုခြင်းအားဖြင့် တိုင်းထွာစမ်းသပ်၍ လျှောက်သဖြင့် ကျွံခြင်း၊ ချွတ် ချော်တိမ်းပါးခြင်း မရှိသည်ဖြစ်၏။” || ‘ခလိုၚ်’ ဟုလည်းရေးသည်။')
,(6315,3,4,'ကြမ်းကျွံ၍ လူပါ အောက်သို့ကျသွားသည်။',NULL)
,(6316,3,1,'ရှင်းလင်းပြောင်နေသောမြေနေရာ။ ကွင်းပြောင်။ ကွင်းပြင်။','ထလာတ်ပွေၚ်ကောန်ၚာ် = ကလေးကစားကွင်း။')
,(6316,3,4,'ပြောင်သည်။ ရှင်းလင်းသည်။','က္ဍိုပ်ထလာတ် = ဦး ခေါင်းပြောင်သည်။')
,(6317,3,4,'ရယ်ရွှင်ဖွယ်လုပ်သည်။','ထလိန်ဗမက် = နောက်ပြောင်သည်၊ ရယ်ရွှင်ဖွယ် လုပ်သည်။')
,(6318,3,4,'ချွဲသည်။ ချွဲကျိကျိဖြစ်သည်။','“ကသ္ကအ်ဂျိုၚ်ၚ်ဂှ် ထလိန်ဒၟံၚ်ရပ်ဝါတ်ရ။” = “ငါးခူ အရှင်သည် ချွဲနေ၍ ကိုင်ရခက်သည်။”')
,(6319,3,4,'လှည့်ဖျားသည်။',NULL)
,(6320,3,4,'မျက်စိနောက်သည်။',NULL)
,(6321,3,4,'ခေါက်သည်။','“တၞးစက္ခူဂှ် ထလပ်ထောံအဒေါဝ်ညိ။” = “စက္ကူအရွက်ကို အလယ်မှခေါက်လိုက်ပါ။”')
,(6322,3,4,'(တံတောင်နှင့်) တွက်သည်။','ထလေဟ်ကဵုတၚ်တဲ = တံတောင်နှင့်တွက်သည်။')
,(6323,3,4,'လွှင့်ပစ်သည်။','“တၞးစက္ခူအဲချူလဝ်လိက်ဂှ် လ္ပထဝေၚ်ထောံညိ။” = “ငါစာရေး ထားသောစက္ကူရွက်ကို လွှင့်မပစ်လိုက်ပါနှင့်။”')
,(6324,3,1,'ခြစ်။','ထဝါတ်သတ်ဗြဴ = အုန်းခြစ်။')
,(6325,3,1,'တင်ပလင်ခွေ။',NULL)
,(6325,3,4,'တင်ပလင်ခွေထိုင်သည်။',NULL)
,(6326,3,1,'ပေါင်ခွင်။ ပေါင်။','“ကောန်ၚာ်သၟတ်ဂှ် ဂ္ဇအ်ဒၟံၚ်ပ္ဍဲထဝဲါဒဳမိဍေံရ။” = “ကလေးငယ်သည် မိခင်၏ပေါင်ခွင်­ ထိုင်နေသည်။”')
,(6327,3,4,'ဝမ်းနည်းကြေကွဲသည်။ ပူဆွေးသောကဖြစ်သည်။','“ညာတ်ဗောဓိသတ်ပကာဂစိုတ်တုဲ မဟာသုဘဒ္ဒါဂှ် မဒှ်တဴတ္ၜိုဟ်သဗထသပါတုဲ လောတ်စှ်ေအာတံဇိုၚ်ဗောဓိသတ်တုဲ သ္ၚဳဒၟံၚ်ရ။” (ဇ—၅၁၄။ အစွောံ။) = “ဘုရားလောင်း (ဆဒ္ဒန်ဆင်မင်း) သေသည်ကိုမြင်သော် မဟာသုဘဒ္ဒါ (ဆင်မင်းမိဖုရား) သည် ရင်­ဆို့နင့်လျက် ဝမ်းနည်းကြေကွဲ ပူဆွေးလွန်းသည်ဖြစ်၍ ဘုရားလောင်းခြေရင်း­ လဲကျသွားကာ မိန်းမောနေလေ၏။” || “မိအဲဟွံဂွံသုၚ်ဍာ် ဟွံဂွံအဟာ ထပှ်တ္ၚဲတုဲရ။ ယာံအဲဗရုပါၚ်တုဲ မိမိၚ်ပါၚ်အဲဗက် သီုလၞီလၞာ်ထသ္ပာ လကိုတ်အာကဵုအဲတုဲ သဒးပ ကာဂစိုတ်ပၠန်ရ” သၟိၚ်စိၚ်ချပ်။ (ဇ—၄၅၅။ အစွောံ။) = “ငါ့မိခင်သည် အစာရေစာမရသည်မှာ ခုနစ်ရက်ရှိပြီ။ ငါနှုတ်သံပြုလိုက်ပါက ငါ့နှုတ်သံကိုကြားသည်နှင့် ငါ့မိခင်သည် ပူဆွေးသောကဖြင့် ငါ့ကိုလန့်၍ သေလေလတ္တံ့” ဟုဆင်မင်းတွေး၏။')
,(6328,3,4,'ကုပ်မှိုင်သည်။ တုန်ရီသည်။',NULL)
,(6329,3,4,'‘ထ္ၜၚ်’ ရှု။',NULL)
,(6330,3,4,'ပြားသည်။',NULL)
,(6331,3,16,'‘ထ္ၜောမ်’ ရှု။',NULL)
,(6332,3,1,'‘ထ္ၜောမ်တလၚ်’ ရှု။',NULL)
,(6333,3,1,'ဆုံ။','ထအဳကဵုရိ = ဆုံနှင့်ကျည်ပွေ့။')
,(6333,3,4,'အိပ်ပျော်နေစဉ်ဟောက်သည်။','‘ဂအဳ’ ဟုလည်းရေးသည်။')
,(6334,3,4,'လူစုလူဝေးနှင့် အသံပြုသည်။ အုတ်အုတ်ကျက်ကျက်အသံပြုသည်။',NULL)
,(6335,3,1,'ညှင်းအရေပြားရောဂါ။',NULL)
,(6336,3,4,'(အိပ်ပျော်နေစဉ်) နှာမှုတ်သည်။ ကျီးသံကဲ့သို့မြည်သည်။','“သ္တိက်လှိၚ်တုဲ — ခမဳ လ္ၚဵုဂှ် ယာံထအိက်တဴဂြံက်ဂြံက်ရ။” (ဇ—၁၆။ အစွောံ။) = “အိပ်ပျော်လတ်သော် အချို့သော သူတို့သည် ဃရုတ်ဃရက်မြည်သော ထွက်သက်ဝင်သက်ရှိကုန်သည်ဖြစ်၍ ကျီးသံကဲ့သို့ မြည် ကုန်၏။”')
,(6337,3,3,'ယုတ်သော။ ရိုင်းသော။','ချေံထအုန် = မြင်းယုတ်။ မဆုံးမရသေးသောမြင်း။ (ပါဠိ—ခဠက/ခဠုၚ်္က/ခလုၚ်္က)')
,(6338,3,4,'ပိတ်သည်။ စေ့သည်။','ထအေပ်တရၚ် = တံခါးကိုစေ့သည်။')
,(6339,3,4,'ချေသည်။ နှာချေသည်။ ချေဆတ်သည်။','“ကၞိက်မြေက်ဂှ် လုပ်အာပ္ဍဲမုဟ် တုဲ ဗမၞးထအဟ်ရ။” (ဇ—၁၂၆။ အစွောံ။) = “ငရုတ်မှုန့်သည် နှာခေါင်းထဲသို့ ဝင်သည်ရှိသော် ပုဏ္ဏားသည် နှာချေ၏။” || “ပ္ဍဲကာလဂှ် ကျာ်တြဲထအှ်တိုန်ရ။” (ဇ—၁၅၅။ အစွောံ။) = “မြတ်စွာဘုရားသည် — တရားကိုဟောတော်မူစဉ် ချေတော်မူ၏။” (ညောင်ကန်)')
,(6340,3,4,'ကြည်းညည်းသည်။ ညည်းညူသည်။ ကျီးသံကဲ့သို့ဟောက်သည်။','(ပါဠိ—နိတ္ထုနတိ/ဝိတ္ထုနတိ) “သၟိၚ်ကုသ ယွီုဂအိဟ်ဒၟံၚ်ဂှ်ပတုဲ ညံၚ်ရဴမသ္ၚဳ အာကီုဂှ် သ္ပရ။ ‘မူရဴညးမွဲ မထအိဟ်ဒၟံၚ်ဂှ်ရော’ ဂးတုဲ ပြဘာဝတဳကျောဝ်ရံၚ်ရ။” (ဇ—၅၃၁။ အစွောံ။) = “ကုသမင်းသည် ကြည်းညည်းသံပြုလျက် မိန်းမောဟန်ပြု၏။ ‘အဘယ်သူသည် ကြည်းညည်းနေသနည်း’ ဟုကြံ၍ ပဘာဝတီသည် ချောင်း၍ကြည့်၏။” (မှတ်ချက်။ မြန်မာ ညောင်ကန်မူ­ ‘ကျည်းဟီး’ ဟုသုံးထားသည်။) || “(မၚ်ဗၠာဲလၞုဟ်ဂှ်) လးယာတ်စဏေဟ် သ တိက်သအိဟ် ကိတ်ေၚက်ကမြေတ်ဒၟံၚ်တုဲ လှိၚ်အာရ။” (ဇ—၇၁။ အစွောံ။) = “ထိုပျင်းရိသော လုလင်သည် အပေါ်လွှမ်းပုဆိုးကိုခင်း၍ အိပ်သည်ရှိသော် ကျီးသံကဲ့သို့ဟောက်လျက် သွားတို့ဖြင့် သွားတို့ကိုကြိတ်လျက် အိပ်ပျော်ခြင်းသို့ရောက်၏။” || “ကဖျုန်ဗွဲမဂၠိုၚ် ဂြောဝ်ဂှ်ဂွံတုဲ စဳရေၚ်လဝ်ဂှ် ခ္ဍာ်ညာတ်တုဲ ပ္ဍဲဗ္တံဂှ် သတိက်ထအိဟ်ဒၟံၚ်ရ။” (ဇ—၂၇၄။ အစွောံ။) = “ကျီးသည် ထိုငါးအမဲ ကိုမြင်၍ စားချင်ခြင်းနှိပ်စက်ရကား မိုးသောက်ထကာလမှစ၍ ညည်းညူလျက်အိပ်၏။”(ညောင်ကန်)')
,(6341,3,4,'မိုမောက်သည်။',NULL)
,(6342,3,4,'အန်သည်။','“ညံၚ်မၚ်ဗၠာဲသတဓမ္မ ထအအ်ပ္တိတ်ပုၚ်သီုဆီတုဲ မဒးလုပ်ချိုတ်အာပ္ဍဲဂြိုပ် ဂှ်—။” (ဇ—၁၇၉။ အစွောံ။) = “သွေးနှင့်တကွသော ထမင်းကိုအန်ထွက်၍ တောသို့ဝင်၍သေ သွားရသော သတဓမ္မလုလင်ကဲ့သို့။” || ‘စအအ်’ ရှု။')
,(6343,3,1,'အိမ်အခြၚ်။','‘ဇအိုအ်’ || ‘ဇအောအ်’ ရှု။')
,(6344,3,4,'လေချဉ်တက်သည်။',NULL)
,(6345,3,12,'(ကြိ) ဋ္ဌာပနာသည်။ ထည့်သွင်းထားသည်။',NULL)
,(6346,3,10,'(ကြိဝိ) အမြဲ။ အစဉ်။ ထာဝရ။','လၟိုန်ထာဝရ = အမြဲထာဝရ။')
,(6347,3,10,'(န) ထိုင်းမှိုင်းခြင်း။ ငိုက်မျဉ်းခြင်း။ ထိနမိဒ္ဓ။',NULL)
,(6348,3,4,'ပြည့်နှက်သည်။ ပြည့်ကျပ်သည်။ ပြည့်သိပ်သည်။','“တိကၠိုဟ်ဂတးအာဂးတုဲ သတ် တအ်ဂမၠိုၚ်ဒြေပ်ဒဴအာ ဗဗွဲလၟေၚ် ဍေံမၞုံဗၞတ်လမၠးမွဲယောဇနာ ဂကောံတိရစ္ဆာန်သက်က် ပေၚ်လေံ ထိမြိတဴရ။” (ဇ—၃၂၂။ အစွောံ။) = “မြေပြိုသည်ဟုဆိုကာ တိရစ္ဆာန်အပေါင်းတို့ ကြောက်၍ ပြေးကြရာ အစဉ်သဖြင့် တစ်ယူဇနာအတိုင်းအရှည်ရှိသော မြေအပြင်­ တိရစ္ဆာန်အပေါင်းတို့သည် ပြည့်နှက်ကျပ်သိပ်လျက်ရှိ၏။” || “တၞဟ်နဗိုၚ်ဒြာဲဂမၠိုၚ် မၞိဟ်တံဂှ် တြဴဗၞတ်မွဲယောဇနာဝွံ ပ္ဍဲ ဂြိုပ်ပ္ဍဲခြုံပ္ဍဲရာပ်တံဂှ် ကဵုၜုၚ်ကဵုတက်ဒရာံဏာ မၞိဟ်ကဵုမၞိဟ်ထိမြိဒၟံၚ်အိုတ်ရ။” (ဇ—၃၈၅။ အစွောံ) = “သမင်များကို ဝိုင်းရန်အလို့ငှာ လူတို့သည် တစ်ယူဇနာရှိသောခရီး­ တောကိုလည်းကောင်း ချုံကိုလည်းကောင်း ရိုက်ကြမောင်းကြကုန်ရာ လူလူချင်း ထိကပ်ပြည့်နှက်လျက်နေ၏။”')
,(6349,3,1,'ဂမုန်းတစ်မျိုး။',NULL)
,(6350,3,3,'များသော၊ ပြည့်စုံသော။',NULL)
,(6351,3,10,'(ကြိ) ရှည်မြင့်စွာတည်သည်။ တည်မြဲသည်။ မြဲမြံသည်။','“တၠပညာနွံပ္ဍဲကွာန်ဂှ် ကွာန်ဂှ် ရာၚ်ဆာဲထဳတိတန်ကြန်ရောၚ်။” (ဇ—၃ဝ၁။ အစွောံ။) = “ပညာရှိတို့နေသောရွာသည် သာယာစည်ပင်၍ အရှည်မြဲမြံတည်တံ့လတ္တံ့။” || “ယွံသမ္ၚေဟ်၊ သၚ်္ခါရဓဝ်အိုဿီုဂှ် ဍေံဟွံဗိုန်ဂၠိ ဟွံထဳတိကဵုသတ္တံညးဂမၠိုၚ်ရောၚ်။” (ဇ—၃၁၇။ အစွောံ။) = “သူကြွယ်၊ အလုံးစုံသော သင်္ခါရတ ရားတို့သည် သတ္တဝါအပေါင်းတို့အား မမြဲမြံမတည်တံ့သောသဘောရှိ၏။” || “မရာတ်ဂွံဗှ်ဗၞုဟ် မဂွံခၠေဝ်ရော်ဂုန်ညး မပ္တုဲလဝ်ပ္ဍဲဇကုဂှ်တုဲ ပ္ဍဲလိုက်ဝွံ မၞိဟ်ဒေဝတဴမဒးထိုၚ်သးရ။ ပိုန်ဟာန်မရာတ် လေဝ် ထဳတိတန်ကြန်ရ။” (ဇ—၄ဝ၉။ အစွောံ။) = “မြတ်သောမင်းကြီး၊ မိမိအားပြုထားအပ် သော သူ့ကျေးဇူးကို အောက်မေ့ခြင်း ပေးဆပ်ခြင်းသည် လောက­ လူနတ်တို့၏ချီးမွမ်းခြင်းကို ရ၏။ အရှင်မင်းမြတ်၏ စည်းစိမ်ဥစ္စာသည်လည်း အရှည်မြဲမြံတည်တံ့၏။” || “နာဲသာဗၞိက်တၠ ပညာဂှ် ဟိုတ်ညးဟွံဒ္ဂေတ်ဗက် စမိန်ပြမာန်ဓဝ်လောဘတုဲ ပိုန်ဋ္ဌဳတိ အယုက်ညးမဂၠိၚ်ရောၚ် ဟွံ သေၚ်ဟာ။” (ဇ—၄၉၃။ အစွောံ။) = “ပညာရှိကုန်သည်ခေါင်းဆောင်သည် လောဘတရားအလို သို့ မလိုက်သည်ဖြစ်၍ ဥစ္စာစည်းစိမ်တည်မြဲ၍ အသက်ရှည်ရသည် မဟုတ်လော။”')
,(6352,3,4,'ရိုက်သည်။ ပုတ်သည်။ ထုသည်။','“(ကလော်ဇၜိုတ်ဂှ်) ဗောဓိသတ်တ္ၜတ်တဲ ဗောဓိသတ်ထုဍေံ ဒးဇကုဍေံ တဲဗောဓိသတ်ကြပ်အာ၊ ဇိုၚ်ဗောဓိသတ်ထနှိက်ဍေံ ဇိုၚ်ဗောဓိသတ်ကြပ် အာ—။” (သၠပတ်ဒ္ၚောဝ်သၜောံ) = “စေးသောကိုယ်အမွေးရှိသောဘီလူးအား ဘုရားလောင်းသည် လက်သီးဆုပ်၍ ရိုက်ပုတ်ရာ ဘီလူးကိုယ်အစေး­ ကပ်ငြိသွား၏။ ဘုရားလောင်းသည် ခြေဖြင့်ကန်ကျောက်ပြန်ရာ ခြေသည်လည်း ဘီလူးကိုယ်အစေး­ ကပ်၏။”')
,(6353,3,11,'(န) ရဟန်းတော်။ ထေရ်။',NULL)
,(6354,3,10,'(န) ထေရဝါဒ။ (ရှင်မဟာကဿပ စသောမထေရ်ကြီးတို့မှ အစဉ်မပျက် ဆင်းသက်လာသော ဗုဒ္ဓသာသနာ။)',NULL)
,(6355,3,10,'(န) ရဟန်းမိန်းမ။ ရဟန်းမ။ ထေရီ။',NULL)
,(6356,3,10,'(န) ရဟန်းတော်၏ အတ္ထုပ္ပတ္တိ။ ထေရုပ္ပတ္တိ။',NULL)
