,(6478,3,4,'‘ထဏိက်’ ရှု။',NULL)
,(6479,3,4,'ကန်သည်။ ကန်ကျောက်သည်။','“ကောကာလိက ထနိက်ပၚုဟ် ဒေဝဒတ်။” (ဇ—၁၄၃။ အစွောံ။) = “ကောကာလိကသည် ဒေဝဒတ်ကို ကန်ကျောက်၍နှိုး၏။”')
,(6480,3,1,'ဟင်းချိုရွက်။',NULL)
